 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Each square outline's interior is colored by its side length parity.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            r0 = min(rr for rr, _ in component)
            r1 = max(rr for rr, _ in component)
            c0 = min(cc for _, cc in component)
            c1 = max(cc for _, cc in component)
            side = r1 - r0 + 1
            if side < 3 or c1 - c0 + 1 != side:
                continue
            outline = (
                all(grid[r0][cc] == color and grid[r1][cc] == color for cc in range(c0, c1 + 1))
                and all(grid[rr][c0] == color and grid[rr][c1] == color for rr in range(r0, r1 + 1))
            )
            if not outline:
                continue
            fill = 7 if side % 2 else 2
            for rr in range(r0 + 1, r1):
                for cc in range(c0 + 1, c1):
                    out[rr][cc] = fill
    return out
